settings.custom_css:
/* Canonical Case Single: template-owned layout only. No per-post selectors. */
selector{font-family:Inter,sans-serif;color:#343434}
selector>.e-div-block-base,selector article.e-div-block-base{display:block;max-width:1200px;margin:0 auto;padding:36px 24px 72px;box-sizing:border-box}
selector .cm-case-cover{width:100%;margin:0 0 36px!important;background:#f3f5f0;border-radius:8px;overflow:hidden}
selector .cm-case-cover img{display:block;width:100%;height:620px;max-height:68vh;object-fit:contain;object-position:center;border-radius:8px}
selector .cm-case-heading{display:flex;align-items:flex-start;gap:16px;padding:0 0 36px!important;margin:0;border-bottom:1px solid #e1e5dd}
selector .cm-case-title .elementor-heading-title{font-family:Kanit,sans-serif;font-size:clamp(30px,3.5vw,48px);font-weight:600;line-height:1.12;text-transform:none;letter-spacing:-.02em;color:#292b26;max-width:1000px;margin:0;text-wrap:balance}
selector .cm-case-summary{width:100%!important;max-width:850px}
selector .cm-case-summary .elementor-heading-title{font:400 18px/1.65 Inter,sans-serif;color:#62685e;text-transform:none;margin:0}
selector .cm-case-location:not(:has(.elementor-post-info__terms-list-item)){display:none}
selector .cm-case-location .elementor-icon-list-items{margin:0;padding:0;list-style:none}
selector .cm-case-location .elementor-post-info__terms-list-item{display:inline-flex;padding:6px 12px;border:1px solid #d9e4d0;border-radius:4px;background:#f1f6ea;color:#397504;font:600 13px/1.4 Inter,sans-serif}
selector .cm-case-body{display:grid!important;grid-template-columns:minmax(0,1fr) 300px;gap:56px;padding:40px 0 0!important;align-items:start}
selector .cm-case-main{display:block;min-width:0;padding:0!important}
selector .cm-case-main .elementor-widget-theme-post-content{width:100%;font:400 16px/1.75 Inter,sans-serif}
selector .cm-case-main h2{font:500 clamp(24px,2.2vw,30px)/1.2 Kanit,sans-serif;color:#292b26;margin:36px 0 14px}
selector .cm-case-main h2:first-child{margin-top:0}
selector .cm-case-main p{margin:0 0 20px}
selector .cm-case-main ul{padding-left:22px;margin:0 0 24px}
selector .cm-case-main a{color:#397504;text-underline-offset:3px}
selector .cm-case-main .gallery{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0 36px!important}
selector .cm-case-main .gallery-item{float:none!important;width:100%!important;max-width:none!important;margin:0!important;padding:0!important;min-width:0}
selector .cm-case-main .gallery-icon{margin:0}
selector .cm-case-main .gallery img{display:block;width:100%!important;height:auto!important;aspect-ratio:4/3;object-fit:contain;background:#f3f5f0;border:0!important;border-radius:6px}
selector .cm-case-main .gallery br{display:none}
selector .cm-case-main iframe{display:block;width:100%;max-width:100%;aspect-ratio:16/9;height:auto;border:0;border-radius:6px}
selector .cm-case-sidebar{width:auto!important;min-width:0;padding:24px!important;border:1px solid #e1e5dd;border-top:3px solid #4e9d05;border-radius:6px;gap:20px;background:#fafbf8}
selector .cm-case-sidebar-title .elementor-heading-title{font:500 25px/1.2 Kanit,sans-serif;margin:0;color:#292b26}
selector .cm-case-facts .elementor-icon-list-items{display:flex;flex-direction:column;align-items:flex-start;gap:16px;margin:0;padding:0}
selector .cm-case-facts .elementor-icon-list-item{padding:0!important;margin:0!important;width:100%}
selector .cm-case-facts .elementor-icon-list-item:not(:has(.elementor-post-info__terms-list-item)){display:none}
selector .cm-case-facts .elementor-icon-list-text{font:500 14px/1.6 Inter,sans-serif;color:#51594b}
selector .cm-case-sidebar p{font:400 14px/1.7 Inter,sans-serif;margin:0;color:#62685e}
selector .cm-case-quote,selector .cm-case-quote .elementor-button-wrapper{width:100%}
selector .cm-case-quote .elementor-button{display:flex;justify-content:center;align-items:center;min-height:52px;padding:12px 18px;border:2px solid #4e9d05;border-radius:8px;background:#4e9d05;color:#fff;font:600 14px/1.3 Inter,sans-serif;text-transform:uppercase;text-decoration:none;transition:background .2s,border-color .2s}
selector .cm-case-quote .elementor-button:hover{background:#397504;border-color:#397504;color:#fff}
selector a:focus-visible{outline:2px solid #397504;outline-offset:4px}
@media(max-width:1024px){selector .cm-case-body{grid-template-columns:minmax(0,1fr) 260px;gap:28px}selector .cm-case-cover img{height:520px;max-height:65vh}}
@media(max-width:767px){selector>.e-div-block-base,selector article.e-div-block-base{padding:24px 20px 48px}selector .cm-case-cover{margin-bottom:28px!important}selector .cm-case-cover img{height:400px;max-height:55vh}selector .cm-case-heading{padding-bottom:28px!important;gap:14px}selector .cm-case-summary .elementor-heading-title{font-size:16px;line-height:1.65}selector .cm-case-body{grid-template-columns:minmax(0,1fr);gap:32px;padding-top:28px!important}selector .cm-case-sidebar{padding:22px!important}selector .cm-case-main .gallery{gap:12px}selector .cm-case-main .gallery img{aspect-ratio:3/4}selector .cm-case-main h2{margin-top:28px}}
@media(prefers-reduced-motion:reduce){selector .elementor-button{transition:none}}

/* Native layout; only intrinsic media, WordPress content and focus need scoped rules. */
.elementor-15714 .cm-case-cover img{display:block;width:auto!important;height:auto!important;max-width:100%;max-height:72vh;margin-inline:auto}
.elementor-15714 .cm-case-main h2{font-family:Kanit,sans-serif;font-size:clamp(20px,1.8vw,26px);font-weight:400;line-height:1.2;letter-spacing:.025em;text-transform:uppercase;margin:32px 0 16px}
.elementor-15714 .cm-case-main h2:first-child{margin-top:0}
.elementor-15714 .cm-case-main .gallery img{border:0!important;width:100%;height:auto}
.elementor-15714 .cm-case-main iframe{width:100%;height:auto;aspect-ratio:16/9;border:0}
.elementor-15714 .elementor-icon-list-item:not(:has(.elementor-post-info__terms-list-item)){display:none}
.elementor-15714 .btn .elementor-button:focus-visible{outline:2px solid var(--e-global-color-accent);outline-offset:4px}
